insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Língua Portuguesa','O trecho “dá muito trabalho” (R.27) constitui uma referência de seu Joaquim à confecção da estante, tarefa que, segundo ele, seria trabalhosa.','Texto original para os itens 1 a 10. No que se refere aos sentidos do texto I, julgue os próximos itens.','/inss-2016/tecnico-texto-1.png','["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
