insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Língua Portuguesa','O trecho seguinte é adequado para compor a parte inicial de um memorando. Brasília, 2 de fevereiro de 2016. À Senhora Ana Silva INSS CEP 70070-946 – Brasília/DF Assunto: Curso de aperfeiçoamento em atendimento ao público','Com base no disposto no Manual de Redação da Presidência da República, julgue o próximo item.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Conhecimentos Básicos','Se, para a infração praticada por Bruno, estiverem previstas as penalidades de advertência ou suspensão, a comissão de ética será competente para, após o regular procedimento, aplicar diretamente a penalidade.','Bruno, servidor contratado temporariamente para prestar serviços a determinado órgão público federal, praticou conduta vedada aos servidores públicos pelo Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal. A partir dessa situação hipotética, julgue os itens a seguir à luz do disposto nos Decretos n.º 1.171/1994 e n.º 6.029/2007.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Conhecimentos Básicos','Mesmo prestando serviço de natureza temporária, Bruno está sujeito às disposições contidas no Decreto n.º 1.171/1994.','Bruno, servidor contratado temporariamente para prestar serviços a determinado órgão público federal, praticou conduta vedada aos servidores públicos pelo Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal. A partir dessa situação hipotética, julgue os itens a seguir à luz do disposto nos Decretos n.º 1.171/1994 e n.º 6.029/2007.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Conhecimentos Básicos','Durante o procedimento de apuração da conduta de Bruno, a comissão de ética deverá garantir-lhe proteção à sua honra e à sua imagem.','Bruno, servidor contratado temporariamente para prestar serviços a determinado órgão público federal, praticou conduta vedada aos servidores públicos pelo Código de Ética Profissional do Servidor Público Civil do Poder Executivo Federal. A partir dessa situação hipotética, julgue os itens a seguir à luz do disposto nos Decretos n.º 1.171/1994 e n.º 6.029/2007.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Conhecimentos Básicos','Embora deva respeitar a hierarquia, o servidor público está obrigado a representar contra ações manifestamente ilegais de seus superiores hierárquicos.','Acerca do disposto nos Decretos n.º 1.171/1994 e n.º 6.029/2007, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Conhecimentos Básicos','O rol de legitimados a provocar a atuação da Comissão de Ética Pública, prevista no Decreto n.º 6.029/2007, é restrito a agentes públicos, sendo, entretanto, permitido a qualquer cidadão provocar a atuação das comissões de ética de que trata o Decreto n.º 1.171/1994.','Acerca do disposto nos Decretos n.º 1.171/1994 e n.º 6.029/2007, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Conhecimentos Básicos','Em razão da relevância do serviço público prestado, é vitalício o mandato de membro integrante da Comissão de Ética Pública, o que evita interferências externas na atuação da comissão.','Acerca do disposto nos Decretos n.º 1.171/1994 e n.º 6.029/2007, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Conhecimentos Básicos','Ainda que o servidor e sua esposa sejam integrantes de órgãos pertencentes a poderes distintos da União, a remoção do servidor poderia ser concedida.','Considerando que determinado servidor público federal tenha sido removido para outra sede, situada em outro município, para acompanhar sua esposa, que também é servidora pública federal e foi removida no interesse da administração, julgue os itens seguintes à luz do disposto na Lei n.º 8.112/1990.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Conhecimentos Básicos','É correto inferir que houve interesse da administração na remoção do servidor, pois esse é um dos requisitos para sua concessão.','Considerando que determinado servidor público federal tenha sido removido para outra sede, situada em outro município, para acompanhar sua esposa, que também é servidora pública federal e foi removida no interesse da administração, julgue os itens seguintes à luz do disposto na Lei n.º 8.112/1990.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Conhecimentos Básicos','A referida remoção pressupõe o deslocamento do cargo ocupado pelo servidor para outro órgão ou entidade do mesmo poder.','Considerando que determinado servidor público federal tenha sido removido para outra sede, situada em outro município, para acompanhar sua esposa, que também é servidora pública federal e foi removida no interesse da administração, julgue os itens seguintes à luz do disposto na Lei n.º 8.112/1990.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Conhecimentos Básicos','O período de afastamento do servidor para o deslocamento e para a retomada do exercício do cargo no novo município, observados os limites legais, é considerado como de efetivo exercício.','Considerando que determinado servidor público federal tenha sido removido para outra sede, situada em outro município, para acompanhar sua esposa, que também é servidora pública federal e foi removida no interesse da administração, julgue os itens seguintes à luz do disposto na Lei n.º 8.112/1990.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Conhecimentos Básicos','Como medida que contribui para a melhoria da qualidade de vida do servidor público, é-lhe facultado optar pela acumulação de períodos de licença-capacitação, caso não seja possível usufruí-los após cada período aquisitivo.','Julgue os itens subsecutivos conforme o disposto na Lei n.º 8.112/1990.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
