insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Conhecimentos Básicos','Em decorrência do princípio da impessoalidade, as realizações administrativo-governamentais são imputadas ao ente público e não ao agente político.','Julgue os itens que se seguem, acerca da administração pública.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Conhecimentos Básicos','Basta que a pessoa nasça no território brasileiro para que seja considerada brasileiro nato, independentemente da nacionalidade dos seus pais, a não ser que algum deles, ou ambos, esteja(m) no Brasil a serviço de seu país.','A respeito dos direitos fundamentais, julgue os itens a seguir.',null,'["Certo", "Errado"]'::jsonb,'A/B/C/D/E','Item anulado no gabarito oficial definitivo. Recebe +1, inclusive em branco.' from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Conhecimentos Básicos','O direito à vida desdobra-se na obrigação do Estado de garantir à pessoa o direito de continuar viva e de proporcionar-lhe condições de vida digna.','A respeito dos direitos fundamentais, julgue os itens a seguir.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Conhecimentos Básicos','Em decorrência do princípio da igualdade, é vedado ao legislador elaborar norma que dê tratamento distinto a pessoas diversas.','A respeito dos direitos fundamentais, julgue os itens a seguir.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
