insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Conhecimentos Básicos','A encampação, que consiste em rescisão unilateral da concessão pela administração antes do prazo acordado, dá ao concessionário o direito a ressarcimento de eventual prejuízo por ele comprovado.','Julgue os seguintes itens, acerca da concessão de serviço público.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
