insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Conhecimentos Básicos','Se o valor da contribuição de um segurado contribuinte individual for superior a R$ 700,00, então o salário-de-contribuição desse indivíduo é superior a R$ 3.500,00.','Art. 21. A alíquota de contribuição dos segurados contribuinte individual e facultativo será de vinte por cento sobre o respectivo salário-de-contribuição. Considerando o art. 21 da Lei n.º 8.212/1991, acima reproduzido, julgue o item seguinte.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Conhecimentos Básicos','A sentença “Bruna, acesse a Internet e verifique a data da aposentadoria do Sr. Carlos!” é uma proposição composta que pode ser escrita na forma p v q.','Julgue os itens a seguir, relativos a raciocínio lógico e operações com conjuntos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Conhecimentos Básicos','Para quaisquer proposições p e q, com valores lógicos quaisquer, a condicional p Y (q Y p) será, sempre, uma tautologia.','Julgue os itens a seguir, relativos a raciocínio lógico e operações com conjuntos.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Conhecimentos Básicos','Caso a proposição simples “Aposentados são idosos” tenha valor lógico falso, então o valor lógico da proposição “Aposentados são idosos, logo eles devem repousar” será falso.','Julgue os itens a seguir, relativos a raciocínio lógico e operações com conjuntos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Conhecimentos Básicos','Dadas as proposições simples p: “Sou aposentado” e q: “Nunca faltei ao trabalho”, a proposição composta “Se sou aposentado e nunca faltei ao trabalho, então não sou aposentado” deverá ser escrita na forma (p v q) Y -p, usando-se os conectivos lógicos.','Julgue os itens a seguir, relativos a raciocínio lógico e operações com conjuntos.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Conhecimentos Básicos','Se A, B e C forem conjuntos quaisquer tais que A, B d C, então (C \ A) 1 (A c B) = C 1 B.','Julgue os itens a seguir, relativos a raciocínio lógico e operações com conjuntos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,51,'Direito Previdenciário','A seguridade social é organizada mediante gestão quadripartite, com participação dos trabalhadores, dos empregadores, dos aposentados e do governo nos órgãos colegiados.','No que se refere à seguridade social no Brasil, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,52,'Direito Previdenciário','A Lei Eloy Chaves, que criou em cada uma das empresas de estradas de ferro existentes no país uma caixa de aposentadoria e pensões para os respectivos empregados, foi o primeiro ato normativo a tratar de seguridade social no Brasil.','No que se refere à seguridade social no Brasil, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,53,'Direito Previdenciário','Na década de 30 do século passado, as caixas de aposentadoria e pensões foram reunidas nos institutos de aposentadoria e pensão, organizados pelo Estado como autarquias federais. Em 1966, esses institutos foram transformados no INPS.','No que se refere à seguridade social no Brasil, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A/B/C/D/E','Item anulado no gabarito oficial definitivo. Recebe +1, inclusive em branco.' from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,54,'Direito Previdenciário','A CF define seguridade social como um conjunto integrado de ações de iniciativa dos poderes públicos e da sociedade destinadas a assegurar direitos relativos à saúde, à previdência e à assistência social.','No que se refere à seguridade social no Brasil, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,55,'Direito Previdenciário','De acordo com o princípio da universalidade da seguridade social, os estrangeiros no Brasil poderão receber atendimento da seguridade social.','No que se refere à seguridade social no Brasil, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,56,'Direito Previdenciário','Lei complementar editada pela União poderá autorizar os estados e o DF a legislar sobre questões específicas relacionadas à seguridade social.','Com relação ao conteúdo e à autonomia da legislação previdenciária, julgue o item abaixo.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,57,'Direito Previdenciário','Situação hipotética: Pedro trabalha como professor remunerado de uma escola particular e, concomitantemente, explora atividade econômica agropecuária em regime de economia familiar em uma chácara de dois módulos fiscais. Assertiva: Nessa situação, Pedro é segurado obrigatório do RGPS em relação a cada uma das atividades realizadas.','Com base no disposto na Lei n.º 8.213/1991, julgue os itens a seguir, acerca dos segurados do RGPS.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,58,'Direito Previdenciário','Brasileiro contratado pela Organização das Nações Unidas, da qual o Brasil faz parte como membro efetivo, é considerado segurado obrigatório do RGPS, mesmo que domiciliado e contratado no exterior, salvo se estiver coberto por regime próprio de previdência social.','Com base no disposto na Lei n.º 8.213/1991, julgue os itens a seguir, acerca dos segurados do RGPS.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,59,'Direito Previdenciário','Pastor evangélico que atue exclusivamente em sua atividade religiosa é considerado segurado facultativo do RGPS.','Com base no disposto na Lei n.º 8.213/1991, julgue os itens a seguir, acerca dos segurados do RGPS.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,60,'Direito Previdenciário','É considerado segurado obrigatório do RGPS na qualidade de contribuinte individual o associado eleito para cargo de direção em cooperativa, associação ou entidade de qualquer natureza, mesmo que não receba remuneração.','Com base no disposto na Lei n.º 8.213/1991, julgue os itens a seguir, acerca dos segurados do RGPS.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
