insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,62,'Direito Previdenciário','O pescador que exerça essa atividade como principal meio de vida é considerado segurado especial mesmo que tenha empregados permanentes.','Com base no disposto na Lei n.º 8.213/1991, julgue os itens a seguir, acerca dos segurados do RGPS.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
