insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,68,'Direito Previdenciário','Os dados constantes dos cadastros informatizados da previdência social, como o Cadastro Nacional de Informações Sociais (CNIS), valem como prova da filiação à previdência social, do tempo de contribuição e dos salários-de-contribuição, desde que acompanhados de outras provas documentais.','A respeito da inscrição e da filiação dos segurados obrigatórios e facultativos na forma do Decreto n.º 3.048/1999, julgue os itens a seguir.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
