insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,70,'Direito Previdenciário','Situação hipotética: João exerce atividade econômica com finalidade lucrativa na sua própria residência. Recentemente, ele contratou Maria para fazer a limpeza de sua residência, de forma habitual e remunerada, e, inclusive, atender clientes. Assertiva: Nessa situação, João será considerado empregador doméstico com relação aos serviços prestados por Maria.','Julgue os itens seguintes à luz do Decreto n.º 3.048/1999 e da CF.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,71,'Direito Previdenciário','Equiparar-se-á a empresa, para os fins do RGPS, a pessoa física que, para fazer uma reforma na própria casa, contratar um mestre de obras e um ajudante.','Julgue os itens seguintes à luz do Decreto n.º 3.048/1999 e da CF.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,72,'Direito Previdenciário','Em caso de eventuais insuficiências financeiras decorrentes do pagamento de benefícios de prestação continuada, a previdência social poderá elevar alíquotas das contribuições sociais de empregados e empregadores até o limite do débito apurado.','Com relação ao financiamento da seguridade social, julgue os seguintes itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,73,'Direito Previdenciário','Além da contribuição proveniente de empregados e empregadores, são fontes de custeio da seguridade social, de forma direta e indireta, os recursos oriundos dos orçamentos da União, dos estados, do DF e dos municípios.','Com relação ao financiamento da seguridade social, julgue os seguintes itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
