insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,79,'Direito Previdenciário','Para efeito de custeio dos benefícios da aposentadoria especial e dos concedidos em razão do grau de incidência de incapacidade laborativa decorrente dos riscos ambientais do trabalho, as alíquotas aplicadas incidem exclusivamente sobre a remuneração do segurado sujeito a condições especiais que lhe prejudiquem a saúde ou a integridade física.','A respeito do custeio da seguridade social, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'A/B/C/D/E','Item anulado no gabarito oficial definitivo. Recebe +1, inclusive em branco.' from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
