insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,81,'Direito Previdenciário','Bruna, empregada da empresa Vargas & Vargas Cia. Ltda., entrou em gozo de licença-maternidade. Nessa situação, haverá incidência da contribuição previdenciária sobre o valor recebido por Bruna a título de salário-maternidade.','Em cada um dos próximos itens, é apresentada uma situação hipotética acerca de salário-de-contribuição, seguida de uma assertiva a ser julgada.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
