insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,83,'Direito Previdenciário','Zilda mantém vínculo empregatício com a empresa Y e com a empresa Z, das quais recebe remuneração mensal equivalente a dois e três salários mínimos, respectivamente. Nessa situação, a contribuição previdenciária de Zilda deverá incidir sobre os valores recebidos de ambos os empregos.','Em cada um dos próximos itens, é apresentada uma situação hipotética acerca de salário-de-contribuição, seguida de uma assertiva a ser julgada.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,84,'Direito Previdenciário','O contrato de trabalho de Carlos, empregado da empresa L & M Ltda., foi rescindido antes que ele pudesse usufruir de férias vencidas. Nessa situação, haverá a incidência de contribuição previdenciária sobre a importância paga a título de indenização das férias vencidas e sobre o respectivo adicional constitucional.','Em cada um dos próximos itens, é apresentada uma situação hipotética acerca de salário-de-contribuição, seguida de uma assertiva a ser julgada.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
