insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,88,'Direito Previdenciário','As contribuições devidas à seguridade social já descontadas dos segurados empregados e não recolhidas até seu vencimento poderão ser objeto de acordo para pagamento parcelado.','A respeito do recolhimento de contribuição previdenciária fora do prazo, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,89,'Direito Previdenciário','As contribuições sociais incluídas ou não em notificação fiscal de lançamento ou inscritas em dívida ativa que forem pagas com atraso estarão sujeitas a atualização monetária, juros de mora e multa, a qual varia entre 8% e 20% sobre o crédito devido.','A respeito do recolhimento de contribuição previdenciária fora do prazo, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,90,'Direito Previdenciário','Iniciada ação fiscal em desfavor de Maria, o juiz responsável pelo processo não poderá deixar de aplicar pena, ainda que Maria efetue os pagamentos devidos, seja ré primária e goze de bons antecedentes.','Maria, proprietária de uma sorveteria situada em uma cidade litorânea, adquiriu, de forma financiada, dois novos freezers para seu estabelecimento comercial. Em razão do período de baixa temporada, ocorreu considerável queda nas vendas da sorveteria, e o seu faturamento tornou-se insuficiente para arcar com todas as despesas. Diante dessa situação e visando honrar com o pagamento das prestações dos freezers, Maria deixou de repassar à previdência social as contribuições previdenciárias recolhidas dos cinco funcionários do estabelecimento, no prazo e na forma legal, tendo incorrido em crime contra seguridade social. Tendo como referência essa situação hipotética e com base nas disposições legais a respeito dos crimes contra a seguridade social, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,91,'Direito Previdenciário','A conduta de Maria configura crime de apropriação indébita previdenciária, para o qual a pena prevista é reclusão e multa.','Maria, proprietária de uma sorveteria situada em uma cidade litorânea, adquiriu, de forma financiada, dois novos freezers para seu estabelecimento comercial. Em razão do período de baixa temporada, ocorreu considerável queda nas vendas da sorveteria, e o seu faturamento tornou-se insuficiente para arcar com todas as despesas. Diante dessa situação e visando honrar com o pagamento das prestações dos freezers, Maria deixou de repassar à previdência social as contribuições previdenciárias recolhidas dos cinco funcionários do estabelecimento, no prazo e na forma legal, tendo incorrido em crime contra seguridade social. Tendo como referência essa situação hipotética e com base nas disposições legais a respeito dos crimes contra a seguridade social, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,92,'Direito Previdenciário','Caso seja interposto recurso contra a decisão que indeferiu o pedido de Mateus, o órgão regional do INSS que proferiu a decisão não poderá reformá-la, devendo encaminhar o recurso à instância competente.','Mateus requereu ao órgão regional do INSS a conversão de auxílio-doença em aposentadoria por invalidez. O INSS indeferiu o pedido de Mateus por considerar que a doença que o acometera era curável, e que, por isso, ele era suscetível de reabilitação. Acerca dessa situação hipotética e dos recursos nos processos administrativos de competência do INSS, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,93,'Direito Previdenciário','Contra a decisão do INSS pelo indeferimento, Mateus poderá interpor recurso administrativo, que será julgado, em primeira instância, pela Câmara de Julgamento da Previdência Social.','Mateus requereu ao órgão regional do INSS a conversão de auxílio-doença em aposentadoria por invalidez. O INSS indeferiu o pedido de Mateus por considerar que a doença que o acometera era curável, e que, por isso, ele era suscetível de reabilitação. Acerca dessa situação hipotética e dos recursos nos processos administrativos de competência do INSS, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,94,'Direito Previdenciário','Dagoberto obteve aposentadoria por tempo de contribuição concedida pelo INSS em junho de 2012. Entretanto, o INSS não efetuou o pagamento do abono anual proporcional do ano de 2012 nem o do ano de 2013. Nessa situação, atualmente, Dagoberto não mais tem direito a exigir o pagamento dos abonos anuais referentes aos anos de 2012 e 2013, visto que está prescrito o direito ao percebimento das referidas prestações.','Com relação a contribuições sociais dos segurados e(ou) a decadência e prescrição relativamente a benefícios previdenciários, cada um dos próximos itens apresenta uma situação hipotética, seguida de uma assertiva a ser julgada.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,95,'Direito Previdenciário','Ronaldo, segurado contribuinte individual da previdência social, optou pela contribuição de alíquota reduzida, de 11%, que exclui o direito ao benefício de aposentadoria por tempo de contribuição. Nessa situação, caso pretenda obter aposentadoria por tempo de contribuição, Ronaldo poderá fazer a complementação da diferença entre o percentual pago e o percentual devido, acrescida de juros moratórios.','Com relação a contribuições sociais dos segurados e(ou) a decadência e prescrição relativamente a benefícios previdenciários, cada um dos próximos itens apresenta uma situação hipotética, seguida de uma assertiva a ser julgada.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,96,'Direito Previdenciário','Um dos critérios para o idoso habilitar-se à concessão do BPC é não possuir outro benefício da seguridade social, excetuados o de assistência médica e a pensão especial de natureza indenizatória.','Julgue os itens seguintes à luz do Decreto n.º 6.214/2007, que regulamenta o BPC da assistência social devido à pessoa com deficiência e ao idoso.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,97,'Direito Previdenciário','O valor a ser pago ao beneficiário do BPC é de um salário mínimo mensal.','Julgue os itens seguintes à luz do Decreto n.º 6.214/2007, que regulamenta o BPC da assistência social devido à pessoa com deficiência e ao idoso.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,98,'Direito Previdenciário','É permitido ao beneficiário do BPC acumular o recebimento desse benefício com o do seguro-desemprego.','Julgue os itens seguintes à luz do Decreto n.º 6.214/2007, que regulamenta o BPC da assistência social devido à pessoa com deficiência e ao idoso.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,99,'Direito Previdenciário','O BPC do idoso que se encontre na condição de acolhimento de longa permanência em hospital será suspenso até a data da sua alta.','Julgue os itens seguintes à luz do Decreto n.º 6.214/2007, que regulamenta o BPC da assistência social devido à pessoa com deficiência e ao idoso.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,100,'Direito Previdenciário','A idade mínima para que um indivíduo passe a ter direito ao BPC do idoso é de sessenta anos.','Julgue os itens seguintes à luz do Decreto n.º 6.214/2007, que regulamenta o BPC da assistência social devido à pessoa com deficiência e ao idoso.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,101,'Direito Previdenciário','No caso de morte do beneficiário do BPC, seus familiares são obrigados a informar tal fato ao INSS, situação em que o pagamento do benefício cessará.','Julgue os itens seguintes à luz do Decreto n.º 6.214/2007, que regulamenta o BPC da assistência social devido à pessoa com deficiência e ao idoso.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,102,'Direito Previdenciário','O centro de referência de assistência social (CRAS) é uma unidade de base estadual e tem por finalidade atender a população de baixa renda e as pessoas que estejam submetidas ao cumprimento de pena de reclusão.','Julgue os próximos itens com base na Lei n.º 8.742/1993, que dispõe sobre a organização da assistência social.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,103,'Direito Previdenciário','O centro de referência especializado de assistência social (CREAS) constitui unidade que presta serviços a indivíduos e famílias que se encontrem em situação de risco pessoal ou social decorrente de violação de direitos.','Julgue os próximos itens com base na Lei n.º 8.742/1993, que dispõe sobre a organização da assistência social.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,104,'Direito Previdenciário','A política de assistência social tem como objetivos, entre outros, a promoção da integração do cidadão ao mercado de trabalho e o amparo às crianças e aos adolescentes carentes.','Julgue os próximos itens com base na Lei n.º 8.742/1993, que dispõe sobre a organização da assistência social.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,105,'Direito Previdenciário','A assistência social organiza-se por meio de um conjunto de serviços e programas que são estratificados em ações de proteção social básica, ações de proteção social secundária e ações de proteção social terciária, sendo essa última direcionada para pessoas em situação de violência.','Julgue os próximos itens com base na Lei n.º 8.742/1993, que dispõe sobre a organização da assistência social.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,106,'Direito Previdenciário','Situação hipotética: O CNAS, por decisão da maioria simples de seus membros, aprovou a proposição, ao Ministério do Planejamento, Orçamento e Gestão, de alteração dos limites de repasse mensal dos benefícios previstos em lei. Assertiva: Nessa situação, a aprovação da proposição ocorreu em conformidade com o que estabelece a Lei n.º 8.742/1993.','Em relação às instâncias deliberativas do SUAS, julgue os itens a seguir à luz da Lei n.º 8.742/1993.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,107,'Direito Previdenciário','Os conselhos estaduais de assistência social e os conselhos municipais de assistência social, instâncias deliberativas do SUAS, têm caráter permanente e composição paritária entre governo e sociedade civil.','Em relação às instâncias deliberativas do SUAS, julgue os itens a seguir à luz da Lei n.º 8.742/1993.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,108,'Direito Previdenciário','O CNAS, instância responsável pela coordenação da PNAS, é presidido alternadamente pelo(a) ministro(a) da previdência social e por um representante eleito da sociedade civil, sendo de dois anos o mandato do seu presidente, permitida a recondução.','Em relação às instâncias deliberativas do SUAS, julgue os itens a seguir à luz da Lei n.º 8.742/1993.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,109,'Direito Previdenciário','O CNAS tem caráter paritário: metade dos seus membros são representantes governamentais e a outra metade é composta por representantes da sociedade civil.','Em relação às instâncias deliberativas do SUAS, julgue os itens a seguir à luz da Lei n.º 8.742/1993.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,110,'Direito Previdenciário','Compete ao CNAS aprovar a PNAS, assim como convocar, ordinariamente, a cada quatro anos, a conferência nacional de assistência social, que terá a atribuição de avaliar a situação da assistência social e propor diretrizes para o aperfeiçoamento do sistema.','Em relação às instâncias deliberativas do SUAS, julgue os itens a seguir à luz da Lei n.º 8.742/1993.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,111,'Direito Previdenciário','Não é considerada doença do trabalho a doença endêmica adquirida por segurado habitante de região em que ela se desenvolva, mesmo que essa doença seja resultante de contato direto determinado pela natureza do trabalho.','Com base no disposto na Lei n. 8.213/1991, que trata dos planos de benefícios da previdência social e dá outras providências, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,112,'Direito Previdenciário','Equipara-se ao acidente do trabalho o acidente sofrido pelo segurado, no local e no horário do trabalho, em consequência de desabamento, inundação, incêndio e outros casos fortuitos ou decorrentes de força maior.','Com base no disposto na Lei n. 8.213/1991, que trata dos planos de benefícios da previdência social e dá outras providências, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,113,'Direito Previdenciário','Em regra, o período de carência para a concessão do benefício de auxílio-doença é de doze contribuições mensais.','Com base no disposto na Lei n. 8.213/1991, que trata dos planos de benefícios da previdência social e dá outras providências, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,114,'Direito Previdenciário','Os princípios que regem a previdência social incluem a uniformidade e a equivalência dos benefícios e serviços prestados às populações urbanas e rurais.','Com base no disposto na Lei n. 8.213/1991, que trata dos planos de benefícios da previdência social e dá outras providências, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,115,'Direito Previdenciário','Compõem o Conselho Nacional de Previdência Social representantes do governo federal e da sociedade civil, a qual é representada por aposentados e pensionistas, trabalhadores em atividade e empregadores.','Com base no disposto na Lei n. 8.213/1991, que trata dos planos de benefícios da previdência social e dá outras providências, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,116,'Direito Previdenciário','A dona de casa e o estudante podem filiar-se facultativamente ao RGPS mediante contribuição, desde que não estejam exercendo atividade remunerada que os enquadre como segurados obrigatórios da previdência social.','Com base no disposto no Decreto n.º 3.048/1999, que aprovou o regulamento da previdência social, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,117,'Direito Previdenciário','A universalidade da cobertura e do atendimento inclui-se entre os princípios que regem as ações dos poderes públicos e da sociedade destinadas a assegurar o direito relativo à saúde, à previdência e à assistência social.','Com base no disposto no Decreto n.º 3.048/1999, que aprovou o regulamento da previdência social, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,118,'Direito Previdenciário','Aquele que presta serviço de natureza contínua, mediante remuneração, a pessoa ou família, no âmbito residencial desta, em atividade sem fins lucrativos, é considerado contribuinte individual, segurado obrigatório da previdência social.','Com base no disposto no Decreto n.º 3.048/1999, que aprovou o regulamento da previdência social, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,119,'Direito Previdenciário','Como Valdemar é segurado de baixa renda da previdência social, ele e seus dependentes fazem jus ao recebimento do valor correspondente ao auxílio-reclusão, que é de um salário mínimo, a ser rateado entre eles.','Em fevereiro de 2016, Valdemar, que era empregado pelo regime celetista e recebia um salário mínimo de sua empregadora, foi demitido e, 30 dias depois, condenado à pena de prisão em regime fechado. Ele é casado com Idalina, com quem tem dois filhos menores. Considerando essa situação hipotética, julgue os itens que se seguem, com base nos regramentos previdenciários acerca do auxílio-reclusão.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,120,'Direito Previdenciário','Assim que terminar de cumprir a pena, Valdemar deixará de ser segurado da previdência social.','Em fevereiro de 2016, Valdemar, que era empregado pelo regime celetista e recebia um salário mínimo de sua empregadora, foi demitido e, 30 dias depois, condenado à pena de prisão em regime fechado. Ele é casado com Idalina, com quem tem dois filhos menores. Considerando essa situação hipotética, julgue os itens que se seguem, com base nos regramentos previdenciários acerca do auxílio-reclusão.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-tecnico' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
