insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,1,'Língua Portuguesa','No texto, a palavra “fortuna” (R.30) pode ser interpretada tanto como sucesso quanto como riqueza.','Texto original para os itens 1 a 9. Julgue o item a partir do texto de apoio.','/inss-2016/analista-texto-1.png','["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,2,'Língua Portuguesa','Do texto não é possível concluir se “o pobre namorado” (R.1) é Antônio Carlos de Oliveira ou o Sr. Dr. Estêvão Soares.','Texto original para os itens 1 a 9. Julgue o item a partir do texto de apoio.','/inss-2016/analista-texto-1.png','["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,3,'Língua Portuguesa','Dada a assinatura “O amigo das letras” (R.31), é correto concluir que o trecho publicado no Jornal do Comércio é uma carta.','Texto original para os itens 1 a 9. Julgue o item a partir do texto de apoio.','/inss-2016/analista-texto-1.png','["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,4,'Língua Portuguesa','Depreende-se do texto que Antônio Carlos de Oliveira vai iniciar uma atividade profissional ligada à propaganda, para a qual tem muito talento.','Texto original para os itens 1 a 9. Julgue o item a partir do texto de apoio.','/inss-2016/analista-texto-1.png','["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,5,'Língua Portuguesa','Na linha 29, a oração introduzida pela preposição “por” remete a uma ação anterior ao estado descrito na oração “Estamos ansiosos”.','Texto original para os itens 1 a 9. Julgue o item a partir do texto de apoio.','/inss-2016/analista-texto-1.png','["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,6,'Língua Portuguesa','A correção gramatical e o sentido do texto seriam mantidos caso o termo “em casa” (R.18) fosse isolado por vírgulas.','Texto original para os itens 1 a 9. Acerca de aspectos linguísticos do texto, julgue os itens a seguir.','/inss-2016/analista-texto-1.png','["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,7,'Língua Portuguesa','Na linha 23, o termo introduzido pela preposição “para” exerce a função de complemento do verbo “pedir”.','Texto original para os itens 1 a 9. Acerca de aspectos linguísticos do texto, julgue os itens a seguir.','/inss-2016/analista-texto-1.png','["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,8,'Língua Portuguesa','Seria alterado o sentido original do texto, embora sua correção gramatical fosse mantida, caso o trecho “Temos o prazer (...) Antônio Carlos de Oliveira” (R. 10 a R. 13) fosse reescrito da seguinte forma: É um prazer informar o país do lançamento da primeira comédia de qualidade do jovem Antônio Carlos de Oliveira, estreante na literatura fluminense.','Texto original para os itens 1 a 9. Acerca de aspectos linguísticos do texto, julgue os itens a seguir.','/inss-2016/analista-texto-1.png','["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,9,'Língua Portuguesa','Na linha 17, o vocábulo “que” classifica-se como conjunção e introduz o sujeito da oração “Consta-nos”.','Texto original para os itens 1 a 9. Acerca de aspectos linguísticos do texto, julgue os itens a seguir.','/inss-2016/analista-texto-1.png','["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,10,'Língua Portuguesa','Verifica-se uma contradição na argumentação do autor, uma vez que o sentido do trecho “criar uma nova comédia com traços muito pessoais” (R. 20 e R. 21) é incompatível com o sentido do trecho “retratou a cultura e os costumes da sociedade do seu tempo” (R. 12 e R. 13).','Texto original para os itens 10 a 12. Julgue os itens subsequentes, que versam sobre os sentidos e os aspectos linguísticos do texto acima.','/inss-2016/analista-texto-2.png','["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,11,'Língua Portuguesa','Depreende-se do texto que Martins Pena começou a fazer sucesso imediatamente após começar a escrever para o Jornal do Comércio.','Texto original para os itens 10 a 12. Julgue os itens subsequentes, que versam sobre os sentidos e os aspectos linguísticos do texto acima.','/inss-2016/analista-texto-2.png','["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,12,'Língua Portuguesa','A substituição de “destacou-se” (R.11) por foi destacado prejudicaria o sentido original do período.','Texto original para os itens 10 a 12. Julgue os itens subsequentes, que versam sobre os sentidos e os aspectos linguísticos do texto acima.','/inss-2016/analista-texto-2.png','["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,13,'Língua Portuguesa','O trecho a seguir apresenta as seguintes características: concisão, clareza, objetividade e formalidade, sendo adequado para constituir parte de um memorando a ser enviado a autoridade com hierarquia igual ou inferior à do signatário. Em resposta ao Mem. 001, informamos que a última reunião de alinhamento do Plano de Ação ocorreu no auditório da sede da DATAPREV, no dia 10 de março de 2016, com a presença do diretor de Gestão de Pessoas, do diretor de Saúde do Trabalhador e do auditor-geral. Atenciosamente,','Com base no disposto no Manual de Redação da Presidência da República, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,14,'Língua Portuguesa','Os trechos a seguir apresentados estão adequados para compor um ofício a ser enviado pelo INSS a um particular. Brasília, 2 de fevereiro de 2016. Ao Digníssimo Senhor Pedro Albuquerque SQS 1016, bloco Z, ap. 001 70.000-900 – Brasília – DF Assunto: Concessão de aposentadoria (…) Respeitosamente, Maria da Silva','Com base no disposto no Manual de Redação da Presidência da República, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,15,'Conhecimentos Básicos','Considerando-se a CF, é correto afirmar que, no cálculo do benefício previdenciário de um servidor do INSS que esteja licenciado do cargo para exercer mandato de deputado federal, os valores serão determinados como se ele estivesse no exercício do cargo na referida autarquia.','Julgue os itens a seguir, que se referem aos direitos e garantias fundamentais previstos na CF e à administração pública.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,16,'Conhecimentos Básicos','Recentemente, o transporte foi incluído no rol de direitos sociais previstos na CF, que já contemplavam, entre outros, o direito à saúde, ao trabalho, à moradia e à previdência social, bem como a assistência aos desamparados.','Julgue os itens a seguir, que se referem aos direitos e garantias fundamentais previstos na CF e à administração pública.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,17,'Conhecimentos Básicos','Sobre a receita de loterias, apostas e sorteio de números incidirá contribuição social destinada a financiar a seguridade social.','No que concerne à disciplina constitucional relativa à seguridade social, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,18,'Conhecimentos Básicos','O serviço público deve-se orientar na estruturação da seguridade social pelos seguintes objetivos, entre outros: equidade na forma de participação no custeio e caráter democrático e descentralizado da administração.','No que concerne à disciplina constitucional relativa à seguridade social, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,19,'Conhecimentos Básicos','Empregado aposentado pelo RGPS, Caio deve, assim como os servidores públicos inativos, contribuir para o custeio da seguridade social.','• Ana, servidora aposentada por RPPS, recebe R$ 6.500,00 de aposentadoria. • Bruno, portador de doença incapacitante devidamente comprovada por perícia médica, é pensionista da União e percebe um benefício de R$ 10.000,00. • Caio aposentou-se recentemente pelo RGPS e recebe o teto do salário-de-benefício. Com relação a essas situações hipotéticas, e considerando que o teto do salário-de-benefício corresponda a R$ 5.189,82, julgue os itens que se seguem com base na CF.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,20,'Conhecimentos Básicos','Bruno não precisa contribuir com a previdência, pois portadores de doença incapacitante comprovada por perícia médica contribuem apenas sobre as parcelas de proventos de aposentadoria e de pensão que superem o dobro do limite máximo estabelecido para os benefícios do RGPS.','• Ana, servidora aposentada por RPPS, recebe R$ 6.500,00 de aposentadoria. • Bruno, portador de doença incapacitante devidamente comprovada por perícia médica, é pensionista da União e percebe um benefício de R$ 10.000,00. • Caio aposentou-se recentemente pelo RGPS e recebe o teto do salário-de-benefício. Com relação a essas situações hipotéticas, e considerando que o teto do salário-de-benefício corresponda a R$ 5.189,82, julgue os itens que se seguem com base na CF.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,21,'Conhecimentos Básicos','De acordo com a CF, incide contribuição previdenciária de 11% sobre o valor total da aposentadoria de Ana, pois seus proventos superam o teto do salário-de-benefício.','• Ana, servidora aposentada por RPPS, recebe R$ 6.500,00 de aposentadoria. • Bruno, portador de doença incapacitante devidamente comprovada por perícia médica, é pensionista da União e percebe um benefício de R$ 10.000,00. • Caio aposentou-se recentemente pelo RGPS e recebe o teto do salário-de-benefício. Com relação a essas situações hipotéticas, e considerando que o teto do salário-de-benefício corresponda a R$ 5.189,82, julgue os itens que se seguem com base na CF.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,22,'Conhecimentos Básicos','Os institutos da desconcentração e da descentralização, essenciais à organização e repartição de competências da administração pública, podem ser exemplificados, respectivamente, pela relação entre o MPS e a União e pela vinculação entre o INSS e o MPS.','Conforme o Decreto n.º 7.556/2011, o INSS é uma autarquia federal vinculada ao MPS e tem por finalidade promover o reconhecimento de direito ao recebimento de benefícios administrados pela previdência social, assegurando agilidade e comodidade aos seus usuários e ampliação do controle social. Considerando essa informação, julgue os itens seguintes, acerca da administração direta e indireta.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,23,'Conhecimentos Básicos','O INSS integra a administração direta do governo federal, uma vez que esse instituto é uma autarquia federal vinculada ao MPS.','Conforme o Decreto n.º 7.556/2011, o INSS é uma autarquia federal vinculada ao MPS e tem por finalidade promover o reconhecimento de direito ao recebimento de benefícios administrados pela previdência social, assegurando agilidade e comodidade aos seus usuários e ampliação do controle social. Considerando essa informação, julgue os itens seguintes, acerca da administração direta e indireta.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,24,'Conhecimentos Básicos','Os filhos de Aldo e Sandra, como dependentes de servidor público, têm direito aos seguintes benefícios do plano de seguridade social: pensão, auxílio-funeral, auxílio-reclusão e assistência à saúde.','Aldo e Sandra são casados e pais de três crianças. Sandra é servidora pública efetiva de determinada fundação pública vinculada ao governo federal, e Aldo, que não é concursado, ocupa um cargo em comissão em um órgão público federal. A partir dessa situação hipotética, julgue os itens a seguir, referentes à seguridade social do servidor público.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,25,'Conhecimentos Básicos','Com base na universalidade da cobertura e do atendimento da seguridade social, Aldo terá direito aos mesmos benefícios de plano de seguridade social e de assistência à saúde garantidos a Sandra.','Aldo e Sandra são casados e pais de três crianças. Sandra é servidora pública efetiva de determinada fundação pública vinculada ao governo federal, e Aldo, que não é concursado, ocupa um cargo em comissão em um órgão público federal. A partir dessa situação hipotética, julgue os itens a seguir, referentes à seguridade social do servidor público.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,26,'Conhecimentos Básicos','É proibido ao servidor público atuar como intermediário junto a repartições públicas, salvo quando se tratar de benefícios previdenciários ou assistenciais de parentes até o segundo grau e de cônjuge ou companheiro.','Com base no disposto no Decreto n.º 6.029/2007 e na Lei n.º 8.112/1990, julgue os itens subsequentes, que versam sobre direitos e deveres de servidores públicos.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,27,'Conhecimentos Básicos','Caso um procedimento instaurado por comissão de ética receba a chancela de reservado, o investigado só terá direito de saber o que lhe está sendo imputado, de conhecer o teor da acusação e de ter vista dos autos após a regular notificação para prestar esclarecimentos.','Com base no disposto no Decreto n.º 6.029/2007 e na Lei n.º 8.112/1990, julgue os itens subsequentes, que versam sobre direitos e deveres de servidores públicos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,28,'Conhecimentos Básicos','O RGPS constitui um gênero do qual são espécies a previdência dos servidores públicos, a dos trabalhadores empregados da iniciativa privada e a dos trabalhadores autônomos.','Com relação ao RGPS, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,29,'Conhecimentos Básicos','O RGPS tem como princípio a universalidade de cobertura, o que significa que os segurados vinculados a esse regime e seus dependentes têm direito aos mesmos benefícios e serviços.','Com relação ao RGPS, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,30,'Conhecimentos Básicos','A contribuição do segurado empregado e a do trabalhador doméstico recaem sobre o valor dos seus salários de contribuição, até um teto máximo fixado por lei.','Julgue o próximo item, relativo ao custeio da seguridade social.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,31,'Conhecimentos Básicos','caso, após seu afastamento do trabalho, Roberto não recupere a saúde, e se comprove a sua incapacidade absoluta para o trabalho, o INSS poderá conceder-lhe aposentadoria por invalidez.','Roberto, empregado na empresa Silva & Silva Ltda. há mais de um ano e oito meses, da qual recebe salário mensal equivalente a um salário mínimo, deverá afastar-se do trabalho por quatro meses em função de um problema cardíaco atestado em perícia do INSS. Nessa situação hipotética,',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,32,'Conhecimentos Básicos','durante o período de quatro meses de afastamento, Roberto fará jus ao recebimento de auxílio-acidente.','Roberto, empregado na empresa Silva & Silva Ltda. há mais de um ano e oito meses, da qual recebe salário mensal equivalente a um salário mínimo, deverá afastar-se do trabalho por quatro meses em função de um problema cardíaco atestado em perícia do INSS. Nessa situação hipotética,',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,33,'Conhecimentos Básicos','Raimunda, segurada da previdência social, conviveu em regime de união estável com Cláudio por doze anos, até falecer. Raimunda não inscreveu Cláudio como seu dependente previdenciário. Nessa situação, caso o INSS exija prova da união estável para a concessão de benefício, Cláudio poderá utilizar-se da justificação administrativa.','Cada um dos próximos itens apresenta uma situação hipotética, seguida de uma assertiva a ser julgada, com referência à manutenção da qualidade de segurado e à justificação administrativa.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,34,'Conhecimentos Básicos','Flávia contribuiu para o RGPS durante seis anos, após os quais deixou de contribuir e perdeu a qualidade de segurada. Nessa situação, caso volte a contribuir para o RGPS, Flávia não poderá computar esses seis anos para efeito de aposentadoria por tempo de contribuição.','Cada um dos próximos itens apresenta uma situação hipotética, seguida de uma assertiva a ser julgada, com referência à manutenção da qualidade de segurado e à justificação administrativa.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,35,'Conhecimentos Básicos','Caso uma pessoa com deficiência que receba BPC passe a exercer atividade remunerada na qualidade de microempreendedor individual, o órgão concedente desse benefício deverá suspendê-lo.','Julgue o item abaixo à luz da Lei n. 8.742/1993 (LOAS) e do Decreto n.º 6.214/2007, que regulamenta o BPC da assistência social devido à pessoa com deficiência e ao idoso.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,36,'Conhecimentos Básicos','O Poder Judiciário pode, de ofício, determinar medida de proteção ao idoso na hipótese de ação ou omissão estatal que viole direito que lhe seja reconhecido no Estatuto do Idoso.','Com fundamento no Estatuto do Idoso e no ECA, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,37,'Conhecimentos Básicos','Conforme o ECA, figura entre as atribuições do conselho tutelar promover a execução de suas decisões, podendo ele, para tanto, requisitar serviço público na área de previdência.','Com fundamento no Estatuto do Idoso e no ECA, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,38,'Conhecimentos Básicos','O acolhimento familiar configura medida de proteção de caráter definitivo da criança e do adolescente.','Com fundamento no Estatuto do Idoso e no ECA, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,39,'Conhecimentos Básicos','A pessoa com deficiência tem o direito de receber cobranças de tributos de forma acessível, independentemente de solicitação.','No que se refere ao Estatuto da Pessoa com Deficiência, julgue os seguintes itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,40,'Conhecimentos Básicos','As escolas particulares podem cobrar dos estudantes com deficiência mensalidades com valores maiores que os das mensalidades cobradas de estudantes sem deficiência.','No que se refere ao Estatuto da Pessoa com Deficiência, julgue os seguintes itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,41,'Conhecimentos Básicos','Ao iniciar seu dia de trabalho, Daniel se deparou com inúmeros aplicativos abertos em seu computador de trabalho, o que deixava sua máquina lenta e sujeita a travamentos frequentes. Ele constatou, ainda, que somente um desses aplicativos era necessário para a execução de suas atividades. Nessa situação, para melhorar o desempenho do seu computador, Daniel deve utilizar um aplicativo de antivírus instalado localmente, para eliminar os aplicativos que estiverem consumindo recursos além do normal.','Cada um dos próximos itens, que abordam procedimentos de informática e conceitos de Internet e intranet, apresenta uma situação hipotética, seguida de uma assertiva a ser julgada.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,42,'Conhecimentos Básicos','A área administrativa do INSS informou a todos os servidores públicos lotados nesse órgão que o acesso a determinado sistema de consulta de dados cadastrais seria disponibilizado por meio da Internet, em substituição ao acesso realizado somente por meio da intranet do órgão. Nessa situação, não haverá similaridade entre os sistemas de consulta, porque sistemas voltados para intranet, diferentemente dos voltados para Internet, não são compatíveis com o ambiente web.','Cada um dos próximos itens, que abordam procedimentos de informática e conceitos de Internet e intranet, apresenta uma situação hipotética, seguida de uma assertiva a ser julgada.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,43,'Conhecimentos Básicos','No explorador de arquivos do Windows 10, é possível fixar as pastas favoritas na funcionalidade acesso rápido, que lista, além das pastas fixadas, as usadas com frequência e também os arquivos usados recentemente.','Acerca de aplicativos para edição de textos e planilhas e do Windows 10, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,44,'Conhecimentos Básicos','Situação hipotética: Elisa recebeu a tarefa de redigir uma minuta de texto a ser enviada para sua chefia superior, com a condição de que todos os servidores do setor pudessem colaborar com a redação da minuta, ficando Elisa encarregada de consolidar o documento final. Após digitar a primeira versão do documento, Elisa compartilhou o respectivo arquivo, a partir de sua estação de trabalho. Todos realizaram a edição do texto no mesmo arquivo por meio do LibreOffice Writer com a função Gravar alterações ativada. Assertiva: Nessa situação, quando da revisão final do texto, Elisa terá acesso a diversas informações, tais como: tipo de alteração, data e hora da alteração e autor da alteração.','Acerca de aplicativos para edição de textos e planilhas e do Windows 10, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,45,'Conhecimentos Básicos','Situação hipotética: Fábio, servidor do INSS, recebeu a listagem dos cinco últimos rendimentos de um pensionista e, para que fosse calculada a média desses rendimentos, ele inseriu os dados no LibreOffice Calc, conforme planilha mostrada abaixo. Assertiva: Nessa situação, por meio da fórmula =MED(A1:A5;5), inserida na célula A6, Fábio poderá determinar corretamente a média desejada.','Acerca de aplicativos para edição de textos e planilhas e do Windows 10, julgue os próximos itens.','/inss-2016/analista-planilha.png','["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,46,'Conhecimentos Básicos','Se, no grupo B, a quantidade de fumantes for igual a 20% do total de pessoas do grupo e a quantidade de ex-fumantes for igual a 30% da quantidade de pessoas fumantes desse grupo, então, escolhendo-se aleatoriamente um indivíduo desse grupo, a probabilidade de ele não pertencer ao conjunto de fumantes nem ao de ex-fumantes será inferior a 70%.','Uma população de 1.000 pessoas acima de 60 anos de idade foi dividida nos seguintes dois grupos: A: aqueles que já sofreram infarto (totalizando 400 pessoas); e B: aqueles que nunca sofreram infarto (totalizando 600 pessoas). Cada uma das 400 pessoas do grupo A é ou diabética ou fumante ou ambos (diabética e fumante). A população do grupo B é constituída por três conjuntos de indivíduos: fumantes, ex-fumantes e pessoas que nunca fumaram (não fumantes). Com base nessas informações, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,47,'Conhecimentos Básicos','Se, das pessoas do grupo A, 280 são fumantes e 195 são diabéticas, então 120 pessoas desse grupo são diabéticas e não são fumantes.','Uma população de 1.000 pessoas acima de 60 anos de idade foi dividida nos seguintes dois grupos: A: aqueles que já sofreram infarto (totalizando 400 pessoas); e B: aqueles que nunca sofreram infarto (totalizando 600 pessoas). Cada uma das 400 pessoas do grupo A é ou diabética ou fumante ou ambos (diabética e fumante). A população do grupo B é constituída por três conjuntos de indivíduos: fumantes, ex-fumantes e pessoas que nunca fumaram (não fumantes). Com base nessas informações, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,48,'Conhecimentos Básicos','Considerando-se as proposições simples “Cláudio pratica esportes” e “Cláudio tem uma alimentação balanceada”, é correto afirmar que a proposição “Cláudio pratica esportes ou ele não pratica esportes e não tem uma alimentação balanceada” é uma tautologia.','Com relação a lógica proposicional, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,49,'Conhecimentos Básicos','Na lógica proposicional, a oração “Antônio fuma 10 cigarros por dia, logo a probabilidade de ele sofrer um infarto é três vezes maior que a de Pedro, que é não fumante” representa uma proposição composta.','Com relação a lógica proposicional, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,50,'Conhecimentos Básicos','Supondo-se que p seja a proposição simples “João é fumante”, que q seja a proposição simples “João não é saudável” e que p Y q, então o valor lógico da proposição “João não é fumante, logo ele é saudável” será verdadeiro.','Com relação a lógica proposicional, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,51,'Serviço Social','O serviço social emergiu como profissão no estágio neoliberal da sociedade capitalista, quando a questão social, por seu caráter de classe, demandou do Estado, além de mecanismos de intervenção econômica, também mecanismos de intervenção política e social.','Acerca do serviço social como profissão, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,52,'Serviço Social','No Brasil, a institucionalização do serviço social como profissão foi provocada pela progressiva intervenção de entidades religiosas no processo de regulação social, quando as manifestações da questão social foram alçadas a objeto de políticas sociais.','Acerca do serviço social como profissão, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,53,'Serviço Social','O trabalho do assistente social como profissional, inscrito na divisão sociotécnica do trabalho, insere-se no processo de mercantilização e valorização do capital.','Acerca do serviço social como profissão, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,54,'Serviço Social','Para a compreensão do significado do serviço social como profissão, é necessário considerá-lo no processo de reprodução das relações sociais, a partir de sua inserção na sociedade, ultrapassando-se a análise de profissão em si mesma.','Acerca do serviço social como profissão, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,55,'Serviço Social','O serviço social como profissão enfrenta uma polarização, uma vez que ele participa tanto do processo de reprodução e preservação do capital quanto das respostas às necessidades de sobrevivência da classe que vive do trabalho.','Acerca do serviço social como profissão, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,56,'Serviço Social','No trabalho do assistente social nos diferentes espaços sócio-ocupacionais em que ele se realiza, verifica-se uma situação de precarização, provocada por fatores tais como: precárias formas de contratação, insegurança do emprego, desvalorização dos salários e pressão pelo aumento da produtividade.','Acerca do serviço social como profissão, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,57,'Serviço Social','O serviço social, desde sua gênese, fundamentou-se em concepções pluralistas acerca do exercício profissional.','No que se refere aos fundamentos históricos, teóricos e metodológicos do serviço social, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,58,'Serviço Social','A década de 70 do século XX foi intensa tanto do ponto de vista teórico quanto no sentido das transformações políticas para o serviço social no Brasil e nos países do Cone Sul da América Latina.','No que se refere aos fundamentos históricos, teóricos e metodológicos do serviço social, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A/B/C/D/E','Item anulado no gabarito oficial definitivo. Recebe +1, inclusive em branco.' from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,59,'Serviço Social','Apesar de haver conexão entre políticas sociais e o serviço social no Brasil desde 1930, a temática da política social foi introduzida nas pautas profissionais tardiamente: na década de 50 no cenário internacional e a partir de 1970 no Brasil.','No que se refere aos fundamentos históricos, teóricos e metodológicos do serviço social, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,60,'Serviço Social','Na década de 30 do século passado, o Estado brasileiro assumiu a questão social como problema de administração, desenvolvendo políticas e agências de poder estatal em diversos setores.','No que se refere aos fundamentos históricos, teóricos e metodológicos do serviço social, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,61,'Serviço Social','O serviço social foi reconhecido nos estatutos legais e éticos como profissão liberal, no entanto, o assistente social, na condição de trabalhador assalariado, não dispõe de total autonomia na efetivação do seu exercício profissional.','No que se refere aos fundamentos históricos, teóricos e metodológicos do serviço social, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,62,'Serviço Social','Na reconceituação do serviço social no Brasil, o núcleo central da perspectiva da reatualização do conservadorismo consistiu na integração e dinamização do processo de desenvolvimento capitalista.','A respeito do movimento de reconceituação do serviço social e da renovação profissional, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,63,'Serviço Social','Sob a perspectiva da vertente modernizadora, um dos objetivos do processo de renovação do serviço social no Brasil foi adequar a profissão às exigências da autocracia burguesa, tendo sido os seminários de Araxá e Teresópolis marcos dessa perspectiva na profissão.','A respeito do movimento de reconceituação do serviço social e da renovação profissional, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,64,'Serviço Social','No Brasil, à época da ditadura militar, marcada pelo desenvolvimento capitalista, o caráter modernizador da perspectiva modernizadora esteve relacionado a uma postura de contestação à ordem sociopolítica então vigente.','A respeito do movimento de reconceituação do serviço social e da renovação profissional, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,65,'Serviço Social','A intenção de ruptura foi forjada com a pretensão de romper com a herança teórico-metodológica conservadora e seus paradigmas de intervenção social.','A respeito do movimento de reconceituação do serviço social e da renovação profissional, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,66,'Serviço Social','O ponto de arranque da perspectiva da intenção de ruptura foi a criação do Centro Brasileiro de Cooperação e Intercâmbio de Serviços Sociais, instituição extrauniversitária que contribuiu para a refuncionalização do sistema universitário e a reconceituação do serviço social no Brasil.','A respeito do movimento de reconceituação do serviço social e da renovação profissional, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,67,'Serviço Social','A intenção de ruptura repercutiu internacionalmente no marco da crise do serviço social, dito então tradicional, e chegou a ser identificada como ponto de partida do movimento de reconceituação.','A respeito do movimento de reconceituação do serviço social e da renovação profissional, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,68,'Serviço Social','A fenomenologia fundamentou teórico-metodologicamente a perspectiva da reatualização do conservadorismo, que centrava sua análise e intervenção na ajuda psicossocial e em valores humanistas.','A respeito do movimento de reconceituação do serviço social e da renovação profissional, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,69,'Serviço Social','Na sociedade capitalista madura, quanto mais se desenvolvem as forças produtivas, mais a produção se torna social, isto é, mais o trabalho se torna amplamente social, enquanto a apropriação de seus frutos é privada, monopolizada por uma parte da sociedade.','Julgue os itens a seguir, relativos à questão social e ao serviço social na contemporaneidade.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,70,'Serviço Social','Os movimentos sociais das classes subalternas expressam o desdobramento sociopolítico das contradições do sistema capitalista que se materializam na questão social.','Julgue os itens a seguir, relativos à questão social e ao serviço social na contemporaneidade.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,71,'Serviço Social','A atual conjuntura sócio-histórica da sociedade consiste em mero pano de fundo para a discussão do trabalho profissional do assistente social.','Julgue os itens a seguir, relativos à questão social e ao serviço social na contemporaneidade.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,72,'Serviço Social','Os atuais instrumentos normativos do serviço social no Brasil, como a Lei de Regulamentação Profissional e o Código de Ética, expressam a materialização do projeto ético-político profissional construído nos últimos trinta anos no seio da categoria.','Julgue os itens a seguir, relativos à questão social e ao serviço social na contemporaneidade.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,73,'Serviço Social','A questão social pode ser apreendida como o conjunto das expressões das desigualdades da sociedade capitalista madura, que têm uma raiz comum, a qual inclui a produção social coletiva e a apropriação privada da riqueza.','Julgue os itens a seguir, relativos à questão social e ao serviço social na contemporaneidade.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,74,'Serviço Social','Na perspectiva do planejamento estratégico situacional, o momento explicativo é representado pelo desenho de ações ou projetos específicos e pela definição dos produtos e resultados esperados.','No que se refere ao planejamento para intervir na realidade social, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,75,'Serviço Social','O planejamento se restringe às decisões técnicas relacionadas à elaboração de um plano, o qual se limita à identificação do que deve ser realizado para a mudança de determinada realidade.','No que se refere ao planejamento para intervir na realidade social, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,76,'Serviço Social','No planejamento estratégico situacional, recomenda-se a análise das motivações dos atores envolvidos para a definição da viabilidade política de determinado programa.','No que se refere ao planejamento para intervir na realidade social, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,77,'Serviço Social','A socialização das informações constitui uma ação de fortalecimento do usuário para acessar determinados bens ou serviços, o que inclui o direito dos usuários de usufruírem de todo conhecimento socialmente produzido.','Acerca das estratégias, dos instrumentos e das técnicas de intervenção utilizados pelo assistente social nos diferentes espaços sócio-ocupacionais, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,78,'Serviço Social','No desempenho de atividades como assessor ou consultor, espera-se que o assistente social realize o estudo da realidade e discuta as demandas e necessidades prioritárias, em conjunto com a equipe da instituição e(ou) dos movimentos sociais a que presta assessoria/consultoria.','Acerca das estratégias, dos instrumentos e das técnicas de intervenção utilizados pelo assistente social nos diferentes espaços sócio-ocupacionais, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,79,'Serviço Social','O profissional assistente social pode dispensar a elaboração prévia de roteiro para a condução de uma oficina se o objetivo desta for facilitar a discussão, incrementar a participação e promover a construção coletiva.','Acerca das estratégias, dos instrumentos e das técnicas de intervenção utilizados pelo assistente social nos diferentes espaços sócio-ocupacionais, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,80,'Serviço Social','O uso da técnica de clarificação em uma entrevista permite que o entrevistado compreenda a situação a partir do ponto de vista do entrevistador, além de estimular a mudança de tema em caso de silêncio prolongado.','Acerca das estratégias, dos instrumentos e das técnicas de intervenção utilizados pelo assistente social nos diferentes espaços sócio-ocupacionais, julgue os itens seguintes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,81,'Serviço Social','Na realização de entrevistas para a elaboração de um parecer social, o assistente social deve ignorar as informações contidas nos prontuários ou processos relativos à situação em estudo, para não ser influenciado na sua opinião técnica.','Considerando que o parecer social no INSS tem como objetivo fornecer elementos para o reconhecimento de direitos, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,82,'Serviço Social','Em se tratando de parecer social com vistas à concessão de um benefício assistencial, o assistente social deve encaminhar ao setor solicitante o parecer por ele elaborado, juntamente com o estudo socioeconômico realizado.','Considerando que o parecer social no INSS tem como objetivo fornecer elementos para o reconhecimento de direitos, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,83,'Serviço Social','O parecer social constitui mecanismo de averiguação de veracidade dos fatos, quando solicitado pela Procuradoria Federal Especializada do INSS, tendo, nessa situação, caráter sigiloso.','Considerando que o parecer social no INSS tem como objetivo fornecer elementos para o reconhecimento de direitos, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,84,'Serviço Social','No caso de a intervenção do assistente social ser feita em conjunto com outros profissionais, a avaliação da situação deve contemplar a opinião da equipe técnica emitida em um documento único assinado por um representante da equipe.','Considerando que o parecer social no INSS tem como objetivo fornecer elementos para o reconhecimento de direitos, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,85,'Serviço Social','O laudo — documento que expressa de forma clara e precisa a conclusão do estudo social — oferece subsídios para a tomada de decisões relativas a direitos sociais.','Considerando que o parecer social no INSS tem como objetivo fornecer elementos para o reconhecimento de direitos, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A/B/C/D/E','Item anulado no gabarito oficial definitivo. Recebe +1, inclusive em branco.' from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,86,'Serviço Social','O parecer social deve conter uma análise prospectiva da situação estudada e indicar hipóteses sobre desdobramentos e consequências da situação.','Considerando que o parecer social no INSS tem como objetivo fornecer elementos para o reconhecimento de direitos, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,87,'Serviço Social','A avaliação para a concessão do BPC às pessoas com deficiência deve orientar-se pelos princípios da Classificação Internacional de Doenças, da Organização Mundial de Saúde.','Com referência à avaliação para a concessão do BPC e da aposentadoria da pessoa com deficiência, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,88,'Serviço Social','A concessão de benefícios destinados às pessoas com deficiência está condicionada a avaliação prévia. No caso de aposentadorias, essa avaliação restringe-se à perícia médica e, no caso do BPC, à avaliação pelo assistente social.','Com referência à avaliação para a concessão do BPC e da aposentadoria da pessoa com deficiência, julgue os próximos itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,89,'Serviço Social','Entre os avanços proporcionados pela matriz teórico-metodológica do serviço social na previdência social, destaca-se a produção teórica específica sobre a política previdenciária e o serviço social, com divulgação em congressos e seminários, publicação de artigos em periódicos e edição de livros.','A respeito da trajetória histórica do serviço social e da legislação que dispõe sobre os planos de benefícios da previdência social, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,90,'Serviço Social','Compete ao serviço social esclarecer aos beneficiários seus direitos sociais e os meios de exercê-los, assim como estabelecer conjuntamente com esses beneficiários o processo de solução dos problemas que emergirem de sua relação com a previdência social.','A respeito da trajetória histórica do serviço social e da legislação que dispõe sobre os planos de benefícios da previdência social, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,91,'Serviço Social','A reabilitação profissional do beneficiário incapacitado parcial ou totalmente inclui o fornecimento de aparelho de prótese, órtese e instrumentos de auxílio para locomoção, quando a perda ou a redução da capacidade funcional puder ser atenuada por seu uso.','A respeito da trajetória histórica do serviço social e da legislação que dispõe sobre os planos de benefícios da previdência social, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,92,'Serviço Social','Atualmente, o serviço social na previdência ultrapassa o discurso da humanização para apoiar-se em sólido conhecimento da realidade, aliado à defesa de direitos dos usuários em conformidade com a matriz teórico-metodológica do serviço social na previdência social e com o projeto ético-político da profissão.','A respeito da trajetória histórica do serviço social e da legislação que dispõe sobre os planos de benefícios da previdência social, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,93,'Serviço Social','A articulação com os movimentos de outras categorias profissionais constitui um dos princípios do Código de Ética do Assistente Social, devendo ultrapassar os limites do corporativismo.','Julgue os itens a seguir à luz do Código de Ética Profissional e do projeto ético-político do serviço social.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,94,'Serviço Social','As alterações realizadas no atual Código de Ética do Assistente Social reafirmam princípios e valores do projeto ético-político ao reconhecer a linguagem de gênero e adotar em todo o texto, simultaneamente, as formas masculina e feminina, além de substituir o termo opção sexual por orientação sexual.','Julgue os itens a seguir à luz do Código de Ética Profissional e do projeto ético-político do serviço social.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,95,'Serviço Social','A precarização das condições de trabalho e da formação profissional, a ausência de preparo técnico e teórico e a fragilização de uma consciência crítica e política são elementos que propiciam o incremento das ideias conservadoras, impondo desafios ao projeto ético-político da profissão.','Julgue os itens a seguir à luz do Código de Ética Profissional e do projeto ético-político do serviço social.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,96,'Serviço Social','A construção do projeto ético-político profissional decorre essencialmente da articulação estabelecida pelas escolas de serviço social do estado de São Paulo.','Julgue os itens a seguir à luz do Código de Ética Profissional e do projeto ético-político do serviço social.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,97,'Serviço Social','A racionalidade da tarefa burocrática pode estimular, na sociedade, a luta por transformações estruturais, especialmente quando ações de setores da burocracia se identificam com os fins do Estado.','Com relação ao Estado moderno e à dominação racional legal, julgue os itens a seguir.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,98,'Serviço Social','Quanto ao exercício do poder político, o Estado pode ser considerado garantidor dos direitos individuais e de ações que visem ao bem comum ou considerado um instrumento de dominação de classe, que não está acima dos conflitos, mas profundamente envolvido neles.','Com relação ao Estado moderno e à dominação racional legal, julgue os itens a seguir.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,99,'Serviço Social','Estado e governo se confundem, pois as instituições em uma sociedade territorialmente definida são ocupadas por dirigentes que governam em nome do Estado.','Com relação ao Estado moderno e à dominação racional legal, julgue os itens a seguir.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,100,'Serviço Social','Na perspectiva da dominação racional legal, funcionários que compõem o quadro administrativo burocrático do Estado são livres e devem obedecer às obrigações objetivas de seu cargo, são nomeados por hierarquia, têm competências funcionais fixas, são contratados de acordo com a qualificação profissional e exercem o cargo como profissão única.','Com relação ao Estado moderno e à dominação racional legal, julgue os itens a seguir.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,101,'Serviço Social','A crise do Estado de bem-estar social manifesta-se pela articulação dos seguintes fatores: o universalismo protetor, as formas crescentes de particularismo social e a mercantilização da política social.','Julgue os próximos itens, referentes ao Estado de bem-estar social e à cidadania.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,102,'Serviço Social','No Brasil, o uso do termo cidadania regulada está relacionado ao direito à previdência assegurado aos cidadãos contribuintes que não possuam vínculo empregatício formal.','Julgue os próximos itens, referentes ao Estado de bem-estar social e à cidadania.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,103,'Serviço Social','A relação entre política social e cidadania é direta e imediata, uma vez que a política social dilui conflitos de classe.','Julgue os próximos itens, referentes ao Estado de bem-estar social e à cidadania.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,104,'Serviço Social','Independentemente da tipologia adotada, é comum às políticas públicas o fato de se constituírem em espaços de poder onde se disputam recursos e a visão de mundo que orienta a ação sobre a realidade.','No que se refere à conceituação de políticas públicas no Estado moderno e ao processo de elaboração dessas políticas, julgue os seguintes itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,105,'Serviço Social','Políticas públicas distributivas são menos conflituosas que políticas redistributivas, uma vez que os recursos destinados às distributivas são alocados pelo Estado, não ficando explícito quem paga ou quem perde com as decisões tomadas pelo poder público.','No que se refere à conceituação de políticas públicas no Estado moderno e ao processo de elaboração dessas políticas, julgue os seguintes itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,106,'Serviço Social','A fase de formulação de uma política pública refere-se ao processo de criação de opções sobre o que fazer a respeito de um problema público, incluindo-se a identificação de restrições técnicas e políticas à ação do Estado.','No que se refere à conceituação de políticas públicas no Estado moderno e ao processo de elaboração dessas políticas, julgue os seguintes itens.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,107,'Serviço Social','Política pública pode ser considerada sinônimo de política estatal, pois é do governo a responsabilidade de identificar os problemas sociais prioritários.','No que se refere à conceituação de políticas públicas no Estado moderno e ao processo de elaboração dessas políticas, julgue os seguintes itens.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,108,'Serviço Social','Conforme as ideias liberais, o Estado vincula-se às iniciativas voltadas para a garantia do patrimônio público, mantendo-se alheio à atividade econômica.','Eric Hobsbawm, historiador britânico, identificou períodos subsequentes do século XIX, como a Era das Revoluções (1789–1848), a Era do Capital (1848–1875) e a Era dos Impérios (1875–1914), que levaram ao triunfo global do capitalismo. Em relação ao que chamou de breve século XX (1914–1991), formado pelo impacto da Revolução Russa, o autor propôs a Era dos Extremos, permeada pela Era da Catástrofe (1914–1945) e pela Era do Ouro (1947–1973). O autor ressalta que talvez a característica mais significativa do fim do século XX seja a tensão entre a acelerada globalização e a incapacidade conjunta das instituições públicas e do comportamento coletivo dos seres humanos de se acomodarem a ela. Tendo o texto acima como referência inicial, julgue os itens seguintes, acerca dos regimes políticos e das principais correntes ideológicas que influenciaram os períodos relatados no texto.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,109,'Serviço Social','A lenta democratização da sociedade burguesa teve, na experiência de 1848, a contribuição decisiva para converter o operariado em sujeito revolucionário e para que segmentos capitalistas reconhecessem a importância de medidas estatais voltadas para mínimas garantias aos trabalhadores e para as reformas sociais.','Eric Hobsbawm, historiador britânico, identificou períodos subsequentes do século XIX, como a Era das Revoluções (1789–1848), a Era do Capital (1848–1875) e a Era dos Impérios (1875–1914), que levaram ao triunfo global do capitalismo. Em relação ao que chamou de breve século XX (1914–1991), formado pelo impacto da Revolução Russa, o autor propôs a Era dos Extremos, permeada pela Era da Catástrofe (1914–1945) e pela Era do Ouro (1947–1973). O autor ressalta que talvez a característica mais significativa do fim do século XX seja a tensão entre a acelerada globalização e a incapacidade conjunta das instituições públicas e do comportamento coletivo dos seres humanos de se acomodarem a ela. Tendo o texto acima como referência inicial, julgue os itens seguintes, acerca dos regimes políticos e das principais correntes ideológicas que influenciaram os períodos relatados no texto.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,110,'Serviço Social','O pressuposto de que a ação do Estado visa assegurar a base legal para que o mercado potencialize os benefícios aos homens é adotado pela ideologia comunista.','Eric Hobsbawm, historiador britânico, identificou períodos subsequentes do século XIX, como a Era das Revoluções (1789–1848), a Era do Capital (1848–1875) e a Era dos Impérios (1875–1914), que levaram ao triunfo global do capitalismo. Em relação ao que chamou de breve século XX (1914–1991), formado pelo impacto da Revolução Russa, o autor propôs a Era dos Extremos, permeada pela Era da Catástrofe (1914–1945) e pela Era do Ouro (1947–1973). O autor ressalta que talvez a característica mais significativa do fim do século XX seja a tensão entre a acelerada globalização e a incapacidade conjunta das instituições públicas e do comportamento coletivo dos seres humanos de se acomodarem a ela. Tendo o texto acima como referência inicial, julgue os itens seguintes, acerca dos regimes políticos e das principais correntes ideológicas que influenciaram os períodos relatados no texto.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,111,'Serviço Social','A vitória do movimento socialista na Rússia em 1917, ao mesmo tempo que representou maior poder coletivo aos trabalhadores, constituiu ameaça à burguesia do Ocidente, refletindo-se diferentemente em cada país. Na Itália, por exemplo, instalou-se o fascismo, regime que imobilizou as organizações dos trabalhadores e militarizou a vida social, favorecendo a dominação dos monopólios.','Eric Hobsbawm, historiador britânico, identificou períodos subsequentes do século XIX, como a Era das Revoluções (1789–1848), a Era do Capital (1848–1875) e a Era dos Impérios (1875–1914), que levaram ao triunfo global do capitalismo. Em relação ao que chamou de breve século XX (1914–1991), formado pelo impacto da Revolução Russa, o autor propôs a Era dos Extremos, permeada pela Era da Catástrofe (1914–1945) e pela Era do Ouro (1947–1973). O autor ressalta que talvez a característica mais significativa do fim do século XX seja a tensão entre a acelerada globalização e a incapacidade conjunta das instituições públicas e do comportamento coletivo dos seres humanos de se acomodarem a ela. Tendo o texto acima como referência inicial, julgue os itens seguintes, acerca dos regimes políticos e das principais correntes ideológicas que influenciaram os períodos relatados no texto.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,112,'Serviço Social','Os princípios que orientam as ações e os serviços públicos de saúde e serviços privados contratados ou conveniados que integram o SUS incluem a universalidade de acesso, a integralidade de assistência e a descentralização político-administrativa.','Com referência à CF e às políticas de seguridade, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,113,'Serviço Social','A humanização como política pública transversal às diferentes ações e instâncias gestoras do SUS sugere trocas solidárias e comprometidas com a dupla tarefa de produção de saúde e produção de sujeitos.','Com referência à CF e às políticas de seguridade, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,114,'Serviço Social','O artigo da CF que prevê os direitos sociais, em consonância com a Declaração Universal dos Direitos Humanos, de 1948, ainda que represente uma conquista, deixou de contemplar o direito básico à moradia ao cidadão brasileiro.','Com referência à CF e às políticas de seguridade, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,115,'Serviço Social','Na organização da seguridade social, o objetivo da universalidade da cobertura e do atendimento diz respeito, mais diretamente, à política de previdência social, dada a superação de sua lógica securitária.','Com referência à CF e às políticas de seguridade, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,116,'Serviço Social','O direito à pensão por morte é assegurado ao cônjuge ou companheiro(a) somente se, no momento do óbito, houver casamento ou união estável por, no mínimo, cinco anos.','Com referência à CF e às políticas de seguridade, julgue os itens subsecutivos.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,117,'Serviço Social','O fortalecimento da estrutura dos conselhos e sua capacidade de execução relaciona-se diretamente ao reconhecimento pelo Estado de que tais conselhos são parte integrante do processo de gestão de políticas públicas.','O processo de redemocratização no Brasil, consolidado na CF, coloca o Estado a serviço do interesse público submetido ao controle social e democrático, a partir de três dimensões distintas e indissociáveis: política, técnica e ética. No que se refere à participação e ao controle social nos processos de gestão de políticas sociais e defesa de direitos sociais, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,118,'Serviço Social','A dimensão política do controle social pode ser observada na mobilização para influir na agenda de um governo mediante a indicação de prioridades. A dimensão técnica, por sua vez, diz respeito ao trabalho da sociedade para fiscalizar a gestão pública, e a dimensão ética refere-se à construção de novos valores e novas referências, fundadas nos ideais de solidariedade, soberania e justiça social.','O processo de redemocratização no Brasil, consolidado na CF, coloca o Estado a serviço do interesse público submetido ao controle social e democrático, a partir de três dimensões distintas e indissociáveis: política, técnica e ética. No que se refere à participação e ao controle social nos processos de gestão de políticas sociais e defesa de direitos sociais, julgue os itens subsequentes.',null,'["Certo", "Errado"]'::jsonb,'A',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,119,'Serviço Social','A pobreza tem natureza conjuntural, e não estrutural, de modo que programas de transferência de renda condicionada alcançam seus objetivos de assegurar o direito à vida a milhões de brasileiros, mas não resolvem a situação de pobreza.','Acerca da heterogeneidade da população brasileira e das profundas mudanças demográficas, econômicas e sociais pelas quais o país tem passado nas últimas décadas, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
insert into public.questions(exam_id,number,subject,text,support,support_image,options,answer,explanation) select id,120,'Serviço Social','São as entidades sociais as responsáveis por garantir à população de idosos no Brasil o direito à concessão de benefícios e à cobertura de programas e serviços como a seguridade social, que engloba saúde, previdência e assistência social.','Acerca da heterogeneidade da população brasileira e das profundas mudanças demográficas, econômicas e sociais pelas quais o país tem passado nas últimas décadas, julgue os itens que se seguem.',null,'["Certo", "Errado"]'::jsonb,'B',null from public.exams where slug='inss-2016-analista-servico-social' on conflict(exam_id,number) do update set subject=excluded.subject,text=excluded.text,support=excluded.support,support_image=excluded.support_image,options=excluded.options,answer=excluded.answer,explanation=coalesce(excluded.explanation,public.questions.explanation);
